import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

// Provider that yields multiple rounds, each with known usage
const multiRoundProviderWithUsage = (rounds: {chunks: MessageChunk[]; usage?: UsageMetadata}[]): AIProvider => {
  let roundIndex = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      const round = rounds[roundIndex++];
      if (round) {
        for (const chunk of round.chunks) yield chunk;
        if (round.usage) {
          yield {type: 'stop', stopReason: 'end_turn', usage: round.usage};
        }
      }
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const promptBuilder = new PromptBuilder({identity: 'Test assistant'});

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};

describe('Report usage across every tool round, not just the last', () => {
  it('accumulates usage from multiple tool rounds into a single total', async () => {
    const usage1: UsageMetadata = {inputTokens: 100, outputTokens: 50, totalTokens: 150};
    const usage2: UsageMetadata = {inputTokens: 50, outputTokens: 75, totalTokens: 125};

    let receivedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      multiRoundProviderWithUsage([
        {chunks: [TOOL_CALL, STOP_FOR_TOOL], usage: usage1},
        {chunks: [{type: 'text', text: 'answer'}, {type: 'stop', stopReason: 'end_turn'}], usage: usage2},
      ]),
      promptBuilder,
      registryReturning({result: 'tool result'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(receivedUsage).toEqual({
      inputTokens: 150,
      outputTokens: 125,
      totalTokens: 275,
    });
  });

  it('turn with no tool calls reports the same usage as before', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    let receivedUsage: UsageMetadata | undefined;

    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, u) => {
        receivedUsage = u;
      },
    };

    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'direct answer'};
        yield {type: 'stop', stopReason: 'end_turn', usage};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('hi'));

    expect(receivedUsage).toEqual(usage);
  });

  it('accumulates reported usage when some rounds report none', async () => {
    const usage1: UsageMetadata = {inputTokens: 100, outputTokens: 50, totalTokens: 150};
    const usage2: UsageMetadata = {inputTokens: 30, outputTokens: 20, totalTokens: 50};

    let receivedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      multiRoundProviderWithUsage([
        {chunks: [TOOL_CALL, STOP_FOR_TOOL], usage: usage1},
        {chunks: [TOOL_CALL, STOP_FOR_TOOL]},
        {chunks: [{type: 'text', text: 'final'}, {type: 'stop', stopReason: 'end_turn'}], usage: usage2},
      ]),
      promptBuilder,
      registryReturning({result: 'tool result'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(receivedUsage).toEqual({
      inputTokens: 130,
      outputTokens: 70,
      totalTokens: 200,
    });
  });

  it('turn with no usage reported on any round passes undefined to hook', async () => {
    let receivedUsage: UsageMetadata | undefined = {inputTokens: 999, outputTokens: 999, totalTokens: 999};
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'answer with no usage'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('hi'));

    expect(receivedUsage).toBeUndefined();
  });
});

